from rest_framework import viewsets, permissions
from rest_framework.decorators import action
from rest_framework.response import Response
from .models import MedicalPrescription
from .serializers import PrescriptionDetailSerializer, PrescriptionExportSerializer

class MedicalPrescriptionViewSet(viewsets.ModelViewSet):
    permission_classes = [permissions.IsAuthenticated]

    def get_queryset(self):
        return MedicalPrescription.objects.filter(clinic=self.request.user.clinic)

    def get_serializer_class(self):
        if self.action == "export_summary":
            return PrescriptionExportSerializer
        return PrescriptionDetailSerializer

    @action(detail=True, methods=["get"])
    def export_summary(self, request, pk=None):
        prescription = self.get_object()
        serializer = self.get_serializer(prescription)
        return Response(serializer.data)
